CREATE TABLE insurance_profile(id VARCHAR(36) PRIMARY KEY, patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), company VARCHAR(160) NOT NULL, plan_name VARCHAR(160) NOT NULL, encrypted_identifiers TEXT NOT NULL, relationship VARCHAR(40) NOT NULL, effective_date VARCHAR(10), expiration_date VARCHAR(10), coverage_order VARCHAR(20) NOT NULL, card_document_id VARCHAR(36) REFERENCES medical_document(id), coverage_summary TEXT, status VARCHAR(20) NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE INDEX insurance_owner ON insurance_profile(patient_id,status);
CREATE TABLE insurance_share(id VARCHAR(36) PRIMARY KEY, profile_id VARCHAR(36) NOT NULL REFERENCES insurance_profile(id), patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), grantee_id VARCHAR(36) REFERENCES app_user(id), department VARCHAR(100), purpose VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX insurance_share_access ON insurance_share(organization_id,profile_id,status);
CREATE TABLE eligibility_check(id VARCHAR(36) PRIMARY KEY, profile_id VARCHAR(36) NOT NULL REFERENCES insurance_profile(id), organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), requester_id VARCHAR(36) NOT NULL REFERENCES app_user(id), provider VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE, summary TEXT NOT NULL, checked_at VARCHAR(40) NOT NULL, request_key VARCHAR(100) NOT NULL, UNIQUE(requester_id,request_key));
CREATE TABLE insurance_plan(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), name VARCHAR(160) NOT NULL, region VARCHAR(120) NOT NULL, network_type VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, monthly_premium DECIMAL(14,2) NOT NULL CHECK(monthly_premium>=0), deductible DECIMAL(14,2) NOT NULL CHECK(deductible>=0), copay VARCHAR(200) NOT NULL, coinsurance VARCHAR(200) NOT NULL, out_of_pocket DECIMAL(14,2) NOT NULL CHECK(out_of_pocket>=0), coverage TEXT NOT NULL, eligibility TEXT NOT NULL, documents_url VARCHAR(1000), status VARCHAR(20) NOT NULL, sponsored BOOLEAN NOT NULL DEFAULT FALSE, sponsorship_enabled BOOLEAN NOT NULL DEFAULT FALSE, synthetic BOOLEAN NOT NULL DEFAULT TRUE, version INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, reviewed_by VARCHAR(36) REFERENCES app_user(id), review_reason VARCHAR(1000));
CREATE TABLE notification_read(user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), event_id VARCHAR(36) NOT NULL REFERENCES organization_event(id), read_at VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,event_id));
